"""Safely execute SQL generated by the model.

Defense in depth: if one layer fails, the remaining layers still block unsafe queries.

1. is_read_query      - accepts only queries starting with SELECT or WITH;
2. mode=ro            - SQLite opens the database in read-only mode;
3. authorizer         - allowlist of actions; anything not listed is denied;
4. single statement   - multiple statements separated by ';' are rejected;
5. timeout            - hanging or unbounded queries are interrupted;
6. row limit          - results are truncated instead of loading everything;
7. object/function deny-lists - internal sqlite_* tables and memory-bomb
                          functions are refused even though reads are allowed.

Requires Python 3.11+ (sqlite3.Connection.setlimit).
"""

from __future__ import annotations

import sqlite3
import time
from pathlib import Path
from typing import Any

PROJECT_ROOT = Path(__file__).resolve().parent.parent
DATABASE_PATH = PROJECT_ROOT / "database" / "querypilot.db"

QUERY_TIMEOUT_SECONDS = 3
MAX_RESULT_ROWS = 1000
MAX_STRING_LENGTH = 1_000_000

# Allowlist: new SQLite actions are denied by default,
# unlike a denylist, which would require explicit handling.
ALLOWED_ACTIONS = frozenset({
    sqlite3.SQLITE_SELECT,
    sqlite3.SQLITE_READ,
    sqlite3.SQLITE_FUNCTION,
    sqlite3.SQLITE_RECURSIVE,
})


# Reads of SQLite internals (sqlite_master, sqlite_stat1, ...) are refused:
# the model is given the schema explicitly and has no need to enumerate it.
INTERNAL_TABLE_PREFIX = "sqlite_"

# Functions that can allocate huge buffers or load native code.
DENIED_FUNCTIONS = frozenset({"load_extension", "zeroblob", "randomblob"})


def _is_allowed(action: int, arg1: str | None, arg2: str | None) -> bool:
    """Decide whether the authorizer should allow one SQLite action."""
    if action not in ALLOWED_ACTIONS:
        return False

    if action == sqlite3.SQLITE_READ and (arg1 or "").lower().startswith(
            INTERNAL_TABLE_PREFIX
    ):
        return False

    if action == sqlite3.SQLITE_FUNCTION and (arg2 or "").lower() in DENIED_FUNCTIONS:
        return False

    return True


def is_read_query(sql: str) -> bool:
    """Initial check: the query must start with SELECT or WITH.

    This is only a preliminary check. The main protection is provided by
    read-only mode and the authorizer.
    """
    query = sql.strip()

    if not query:
        return False

    # Remove leading SQL comments.
    while query:
        query = query.lstrip()

        if query.startswith("--"):
            newline = query.find("\n")
            if newline == -1:
                return False
            query = query[newline + 1:]
            continue

        if query.startswith("/*"):
            end = query.find("*/")
            if end == -1:
                return False
            query = query[end + 2:]
            continue

        break

    first_word = query.split(None, 1)[0].upper() if query else ""

    return first_word in {"SELECT", "WITH"}


def execute_read_only(
        sql: str,
        database_path: Path | str | None = None,
        timeout_seconds: float | None = None,
        max_rows: int | None = None,
) -> dict[str, Any]:
    """Execute one read-only SQL query.

    Return a dictionary containing columns, rows, truncated, and execution_time_seconds.

    Exceptions:
        ValueError            - query does not start with SELECT/WITH;
        FileNotFoundError     - database file does not exist;
        sqlite3.Error         - SQL error, forbidden action, timeout,
                                or multiple statements.
    """
    if not is_read_query(sql):
        raise ValueError("Only SELECT or WITH queries are allowed.")

    path = Path(database_path) if database_path is not None else DATABASE_PATH
    timeout = QUERY_TIMEOUT_SECONDS if timeout_seconds is None else timeout_seconds
    row_limit = MAX_RESULT_ROWS if max_rows is None else max_rows

    if not path.exists():
        raise FileNotFoundError(f"Database not found: {path}")

    connection = sqlite3.connect(
        path.resolve().as_uri() + "?mode=ro",
        uri=True,
        timeout=timeout,
    )

    start_time = time.monotonic()

    try:
        def authorizer(
                action: int,
                arg1: str | None,
                arg2: str | None,
                database_name: str | None,
                trigger_name: str | None,
        ) -> int:
            if _is_allowed(action, arg1, arg2):
                return sqlite3.SQLITE_OK

            return sqlite3.SQLITE_DENY

        connection.set_authorizer(authorizer)

        # Protect against queries that allocate huge strings in memory
        # (for example, printf('%1000000000d', 1)). Python 3.11+.
        connection.setlimit(sqlite3.SQLITE_LIMIT_LENGTH, MAX_STRING_LENGTH)

        # SQLite periodically calls this callback during execution.
        # A nonzero return value interrupts the query on timeout.
        def progress_handler() -> int:
            return int(time.monotonic() - start_time > timeout)

        connection.set_progress_handler(progress_handler, 1000)

        cursor = connection.execute(sql)

        columns = [item[0] for item in (cursor.description or [])]
        rows = cursor.fetchmany(row_limit + 1)

        truncated = len(rows) > row_limit

        return {
            "columns": columns,
            "rows": [tuple(row) for row in rows[:row_limit]],
            "truncated": truncated,
            "execution_time_seconds": round(time.monotonic() - start_time, 4),
        }

    finally:
        connection.close()
